Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

Definition PC_pixClearAll : Z := 0x6e4b4.
Definition CLR_STACK : Z := 16 + LSF.     (* [comment removed for export] *)

Section ClearAll.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Variable rom : word -> option byte.

  Definition FR1 (m : word -> option byte) (s : Z) (ret : word) : word -> option byte :=
    wbytes m (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret).

  (* [comment removed for export] *)
  Lemma pca_A : forall regs m (s pix : Z) (v : pixv) (ret : word),
    (16 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pix)%Z -> PIXat (FR1 m s ret) pix v ->
    (0 <= p_wpl v * p_h v)%Z -> (4 * (p_wpl v * p_h v) < 2 ^ 31)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 16)) 16 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pix ->
    exists regs',
      msteps SEGS (mkst regs (0x6e4b4 : word) m rom) (mkst regs' (0x10a230 : word) (FR1 m s ret) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 16) /\ getr regs' 1 = Z_to_bv 64 0x6e4dc
      /\ getr regs' 10 = Z_to_bv 64 (p_data v) /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 12 = Z_to_bv 64 (4 * (p_wpl v * p_h v))
